package com.cpf.starter.realtime;import java.util.function.Supplier;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.context.annotation.Bean;import org.springframework.web.reactive.function.client.WebClient;import org.springframework.web.reactive.socket.client.*;@AutoConfiguration @ConditionalOnProperty(prefix="cpf.integration.realtime",name="enabled",havingValue="true") public class CpfRealtimeAutoConfiguration {@Bean @ConditionalOnMissingBean WebSocketClient cpfWebSocketClient(){return new ReactorNettyWebSocketClient();}@Bean CpfRealtimeClient cpfRealtimeClient(WebSocketClient ws,org.springframework.beans.factory.ObjectProvider<Supplier<String>> token,org.springframework.core.env.Environment e){Supplier<String> t=token.getIfAvailable();if(t==null)throw new IllegalStateException("Realtime client requires auth token supplier");int max=e.getProperty("cpf.integration.realtime.max-buffered",Integer.class,1000);if(max<1)throw new IllegalStateException("max-buffered must be positive");return new CpfRealtimeClient(WebClient.builder().build(),ws,t,max);}}
